// Headless promo screenshots for the Now Playing page.
//
// Run with:
//   flutter test test/promo_shots_test.dart
//
// To save PNGs, set LEKIS_UI_CAPTURE_DIR (and optionally LEKIS_UI_FONT /
// LEKIS_UI_ICONS for CJK glyphs and Material icons); no desktop window is
// opened and nothing is uploaded.  The demo covers are original fixtures
// generated by tools/demo-library.

import 'dart:io';
import 'dart:typed_data';
import 'dart:ui' as ui;

import 'package:flutter/rendering.dart';
import 'package:flutter/services.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:lekis/src/bridge/core_events.dart';
import 'package:lekis/src/features/downloads/downloads_providers.dart';
import 'package:lekis/src/features/library/library_providers.dart';
import 'package:lekis/src/features/now_playing/lyrics_parser.dart';
import 'package:lekis/src/features/now_playing/now_playing_page.dart';
import 'package:lekis/src/features/now_playing/now_playing_providers.dart';
import 'package:lekis/src/features/now_playing/now_playing_style.dart';
import 'package:lekis/src/features/player/player_providers.dart';
import 'package:lekis/src/features/settings/settings_providers.dart';
import 'package:lekis/src/l10n/app_l10n.dart';
import 'package:lekis/src/platform/ui_profile.dart';
import 'package:lekis/src/rust/api/dto.dart';
import 'package:lekis/src/rust/frb_generated.dart';
import 'package:lekis/src/theme/theme.dart';
import 'package:material_ui/material_ui.dart';

class _Playback extends PlaybackController {
  @override
  PlaybackUiState build() => const PlaybackUiState(
    state: PlaybackStateDto.playing,
    trackId: 16,
    durationMs: 210000,
    queueLength: 18,
    queueIndex: 0,
  );
}

class _Position extends PositionController {
  @override
  int build() => 42000;
}

class _Settings extends SettingNotifier {
  _Settings(super.key);

  @override
  Future<String?> build() async => null;
}

class _ArtworkApi implements RustLibApi {
  _ArtworkApi(this.path);
  final String path;

  @override
  String crateApiCoreArtworkPath({required String hash, required int width}) =>
      path;

  @override
  dynamic noSuchMethod(Invocation invocation) => super.noSuchMethod(invocation);
}

const _coverHash = 'demo-starlit-reverie';
final _palette = PaletteDto(
  primary: 0x8F7BFF,
  secondary: 0x1A1240,
  onPrimary: 0xFFFFFF,
  gradient: Uint32List.fromList([0x1A1240, 0x0B0A1E, 0x2B1B4D, 0x08060F]),
);

TrackDto _track() => TrackDto(
  id: 16,
  uid: 'demo-starlit-reverie',
  title: 'Starlit Reverie',
  artists: const ['Hoshimiya'],
  albumId: 6,
  albumTitle: 'Starlit Reverie',
  trackNo: 1,
  year: 2026,
  durationMs: BigInt.from(210000),
  genres: const ['Anime / Dream Pop'],
  qualityBadge: 'FLAC',
  loved: false,
  playCount: 0,
  isLocal: true,
);

LyricsDto _lyrics() => LyricsDto(
  format: LyricsFormatDto.lrc,
  content: File('test/fixtures/demo/starlit-reverie.lrc').readAsStringSync(),
  source: 'sidecar',
  offsetMs: 0,
  confidence: 1,
);

ProviderContainer _container({required NowPlayingPane pane}) {
  final container = ProviderContainer(
    overrides: [
      coreEventSourceProvider.overrideWithValue(const Stream.empty()),
      playbackProvider.overrideWith(_Playback.new),
      positionProvider.overrideWith(_Position.new),
      currentTrackProvider.overrideWith((ref) async => _track()),
      currentArtworkProvider.overrideWith(
        (ref) async => ArtworkDto(
          id: 6,
          hash: _coverHash,
          source: 'sidecar',
          width: 1200,
          height: 1200,
          palette: _palette,
        ),
      ),
      artistIdForNameProvider.overrideWith((ref, name) async => null),
      artistProvider.overrideWith(
        (ref, id) async => const ArtistDto(id: 0, name: 'Hoshimiya', aliases: []),
      ),
      artistAlbumsProvider.overrideWith((ref, id) async => []),
      artistTracksProvider.overrideWith((ref, id) async => []),
      settingProvider.overrideWith2((key) => _Settings(key)),
      downloadStateProvider.overrideWith((ref, id) => null),
      downloadProgressProvider.overrideWith((ref, id) => null),
      lyricsProvider.overrideWith(
        (ref, id) async => ParsedLyrics.parse(_lyrics()),
      ),
    ],
  );
  container.read(nowPlayingPaneProvider.notifier).set(pane);
  return container;
}

Future<void> _pump(
  WidgetTester tester,
  ProviderContainer container, {
  required Size size,
  required GlobalKey boundaryKey,
  double devicePixelRatio = 1,
}) async {
  tester.view.physicalSize = size * devicePixelRatio;
  tester.view.devicePixelRatio = devicePixelRatio;
  addTearDown(tester.view.reset);
  final theme = lekisDarkTheme();
  final font = Platform.environment['LEKIS_UI_FONT'];
  final promoTheme = font == null
      ? theme
      : theme.copyWith(
          textTheme: theme.textTheme.apply(fontFamily: 'PromoFont'),
          primaryTextTheme: theme.primaryTextTheme.apply(
            fontFamily: 'PromoFont',
          ),
        );
  await tester.pumpWidget(
    UncontrolledProviderScope(
      container: container,
      child: LekisLocale(
        locale: const Locale('zh'),
        child: MaterialApp(
          theme: promoTheme,
          builder: (context, child) => MediaQuery(
            data: MediaQuery.of(
              context,
            ).copyWith(disableAnimations: true, reduceMotion: true),
            child: RepaintBoundary(key: boundaryKey, child: child!),
          ),
          home: const NowPlayingPage(),
        ),
      ),
    ),
  );
  await tester.pumpAndSettle();
}

Future<void> _snapshot(
  WidgetTester tester,
  GlobalKey key,
  String name, {
  double pixelRatio = 1,
}) async {
  final capture = Platform.environment['LEKIS_UI_CAPTURE_DIR'];
  if (capture == null) return;
  // Let the file-backed artwork decode before taking the image.
  for (var attempt = 0; attempt < 40; attempt++) {
    final raw = find.byType(RawImage);
    if (raw.evaluate().isEmpty || tester.widget<RawImage>(raw.first).image != null) {
      break;
    }
    await tester.runAsync(
      () => Future<void>.delayed(const Duration(milliseconds: 10)),
    );
    await tester.pumpAndSettle();
  }
  await tester.runAsync(() async {
    final boundary =
        key.currentContext!.findRenderObject()! as RenderRepaintBoundary;
    final image = await boundary.toImage(pixelRatio: pixelRatio);
    final bytes = await image.toByteData(format: ui.ImageByteFormat.png);
    await Directory(capture).create(recursive: true);
    await File('$capture/$name.png').writeAsBytes(
      bytes!.buffer.asUint8List(),
    );
    image.dispose();
  });
}

void main() {
  final boundaryKey = GlobalKey();

  setUpAll(() async {
    final fontPath = Platform.environment['LEKIS_UI_FONT'];
    if (fontPath != null) {
      final bytes = ByteData.sublistView(await File(fontPath).readAsBytes());
      // The app theme names Windows system families directly; register the
      // same test font under those names so headless rendering has glyphs.
      for (final family in const [
        'PromoFont',
        'Roboto',
        'Segoe UI Variable Text',
        'Segoe UI Variable Display',
        'Segoe UI',
        'Microsoft YaHei UI',
        'Microsoft YaHei',
        'Yu Gothic UI',
        'Malgun Gothic',
      ]) {
        await (FontLoader(family)..addFont(Future.value(bytes))).load();
      }
    }
    final iconPath = Platform.environment['LEKIS_UI_ICONS'];
    if (iconPath != null) {
      final bytes = ByteData.sublistView(await File(iconPath).readAsBytes());
      await (FontLoader('MaterialIcons')..addFont(Future.value(bytes))).load();
    }
  });

  setUp(() {
    UiProfile.debugOverride = UiProfile.desktop;
    RustLib.initMock(
      api: _ArtworkApi(
        File('test/fixtures/demo/starlit-reverie.jpg').absolute.path,
      ),
    );
  });
  tearDown(() {
    UiProfile.debugOverride = null;
    RustLib.dispose();
  });

  testWidgets('desktop now playing with classic lyrics', (tester) async {
    final container = _container(pane: NowPlayingPane.lyrics);
    addTearDown(container.dispose);
    await _pump(
      tester,
      container,
      size: const Size(1600, 965),
      boundaryKey: boundaryKey,
    );
    await _snapshot(tester, boundaryKey, 'desktop-now-playing-lyrics');
    expect(find.byType(NowPlayingPage), findsOneWidget);
  });

  testWidgets('desktop now playing with the vinyl treatment', (tester) async {
    final container = _container(pane: NowPlayingPane.cover);
    addTearDown(container.dispose);
    container
        .read(nowPlayingStyleProvider.notifier)
        .restore(NowPlayingStyle.vinyl);
    await _pump(
      tester,
      container,
      size: const Size(1600, 965),
      boundaryKey: boundaryKey,
    );
    await _snapshot(tester, boundaryKey, 'desktop-now-playing-vinyl');
    expect(find.byType(NowPlayingPage), findsOneWidget);
  });

  testWidgets('mobile now playing portrait', (tester) async {
    UiProfile.debugOverride = UiProfile.mobile;
    addTearDown(() => UiProfile.debugOverride = null);
    final container = _container(pane: NowPlayingPane.cover);
    addTearDown(container.dispose);
    await _pump(
      tester,
      container,
      size: const Size(412, 892),
      devicePixelRatio: 2,
      boundaryKey: boundaryKey,
    );
    await _snapshot(
      tester,
      boundaryKey,
      'mobile-now-playing',
      pixelRatio: 2,
    );
    expect(find.byType(NowPlayingPage), findsOneWidget);
  });

  testWidgets('mobile vinyl portrait', (tester) async {
    UiProfile.debugOverride = UiProfile.mobile;
    addTearDown(() => UiProfile.debugOverride = null);
    final container = _container(pane: NowPlayingPane.cover);
    addTearDown(container.dispose);
    container
        .read(nowPlayingStyleProvider.notifier)
        .restore(NowPlayingStyle.vinyl);
    await _pump(
      tester,
      container,
      size: const Size(412, 892),
      devicePixelRatio: 2,
      boundaryKey: boundaryKey,
    );
    await _snapshot(tester, boundaryKey, 'mobile-vinyl', pixelRatio: 2);
    expect(find.byType(NowPlayingPage), findsOneWidget);
  });
}
